-- ===== Zahiriddin Muhammad Bobur =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Захириддин Мухаммад Бабур?', fact_ru = 'Я родился 14 февраля 1483 года в Андижане. Мой отец — правитель Ферганы Умаршайх Мирза, а сам я из рода Амира Темура.' WHERE id = 170;
UPDATE fact_cards SET topic_ru = '«Бабурнаме»', question_ru = 'Что за книга «Бабурнаме» и о чём она?', fact_ru = 'Это книга, написанная мной на родном языке, — о моей жизни, о виденных городах, растениях и людях. Она считается одним из первых мемуаров в мировой литературе.' WHERE id = 171;
UPDATE fact_cards SET topic_ru = 'Поход в Индию', question_ru = 'Какое государство основал Бабур в Индии?', fact_ru = 'В 1526 году я одержал победу в битве при Панипате и основал в Индии новое государство. Позже его назвали державой Бабуридов.' WHERE id = 172;
UPDATE fact_cards SET topic_ru = 'Тоска по родине', question_ru = 'Как в стихах Бабура отразилась тоска по родине?', fact_ru = 'Большая часть моей жизни прошла вдали от родины. Тоска по Андижану и Фергане часто встречается в моих стихах.' WHERE id = 173;
UPDATE fact_cards SET topic_ru = 'Ферганский трон', question_ru = 'В каком возрасте Бабур взошёл на ферганский трон?', fact_ru = 'Когда умер мой отец, мне было 12 лет, и я взошёл на ферганский трон.' WHERE id = 174;
UPDATE fact_cards SET topic_ru = 'Моя борьба за Самарканд', question_ru = 'Какой город Бабур пытался занять в юности?', fact_ru = 'В юности я не раз пытался занять Самарканд — столицу моего великого предка Амира Темура — и дважды брал его. Но удержать трон надолго не смог.' WHERE id = 1540;
UPDATE fact_cards SET topic_ru = 'Моё правление в Кабуле', question_ru = 'Какой город Бабур занял в 1504 году и сделал своей столицей?', fact_ru = 'В 1504 году я занял Кабул и укрепил там своё государство. Кабул многие годы был моей столицей.' WHERE id = 1541;
UPDATE fact_cards SET topic_ru = 'Битва при Панипате', question_ru = 'В какой знаменитой битве Бабур одержал победу в 1526 году?', fact_ru = 'В 1526 году в битве при Панипате я разбил войско делийского султана Ибрахима Лоди. Эта победа открыла мне путь к основанию нового государства в Индии.' WHERE id = 1542;
UPDATE fact_cards SET topic_ru = 'Династия Бабуридов', question_ru = 'Сколько времени правила в Индии основанная Бабуром династия?', fact_ru = 'Основанная мной династия Бабуридов правила в Индии более трёх веков. Среди моих потомков — Акбаршах и Шах-Джахан, построивший Тадж-Махал.' WHERE id = 1543;
UPDATE fact_cards SET topic_ru = 'Мой труд «Мубайин»', question_ru = 'Как называется стихотворный труд, написанный Бабуром для своих детей?', fact_ru = 'Для своих детей я написал труд под названием «Мубайин». В нём я стихами и понятно изложил религиозные правила.' WHERE id = 1544;
UPDATE fact_cards SET topic_ru = 'Письмо Бабури', question_ru = 'Как называется письменность, изобретённая Бабуром?', fact_ru = 'Я сам изобрёл новый алфавит — он называется «хатти Бабури». Этим письмом переписывали и некоторые книги.' WHERE id = 1545;
UPDATE fact_cards SET topic_ru = 'Мой трактат об арузе', question_ru = 'Как называется трактат Бабура, посвящённый стихотворному размеру аруз?', fact_ru = 'Я написал трактат о науке стиха под названием «Мухтасар». В нём подробно объяснил правила размера аруз.' WHERE id = 1546;
UPDATE fact_cards SET topic_ru = 'Мои газели и рубаи', question_ru = 'В каких поэтических жанрах творил Бабур?', fact_ru = 'Кроме «Бабурнаме» я написал множество газелей и рубаи. Мои стихи собраны в диван и любимы читателями по сей день.' WHERE id = 1547;
UPDATE fact_cards SET topic_ru = 'Моя мать Кутлуг Нигорханым', question_ru = 'Чьей дочерью была мать Бабура Кутлуг Нигорханым?', fact_ru = 'Моя мать Кутлуг Нигорханым была дочерью Юнусхана. В тяжёлые дни она всегда была рядом и поддерживала меня.' WHERE id = 1548;
UPDATE fact_cards SET topic_ru = 'Моя могила — сад Бабура', question_ru = 'Где похоронен Бабур?', fact_ru = 'По моему завещанию мой прах позже перенесли в любимый мною сад в Кабуле. Это место теперь называется садом Бабура, и многие приходят туда поклониться.' WHERE id = 1549;

-- ===== Abdulla Qodiriy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Абдулла Кадыри?', fact_ru = 'Я родился в 1894 году в Ташкенте, в семье садовника.' WHERE id = 175;
UPDATE fact_cards SET topic_ru = '«Минувшие дни»', question_ru = 'Почему «Минувшие дни» важны для узбекской литературы?', fact_ru = '«Минувшие дни» — первый роман в узбекской литературе. В нём изображены жизнь эпохи ханств и судьба Отабека и Кумуш.' WHERE id = 176;
UPDATE fact_cards SET topic_ru = '«Скорпион из алтаря»', question_ru = 'О чём роман Абдуллы Кадыри «Скорпион из алтаря»?', fact_ru = 'Мой второй роман написан на основе событий при дворе Худояр-хана.' WHERE id = 177;
UPDATE fact_cards SET topic_ru = 'Джулкунбай', question_ru = 'Под каким псевдонимом Абдулла Кадыри публиковал сатирические произведения?', fact_ru = 'Свои сатирические произведения я публиковал под псевдонимом «Джулкунбай».' WHERE id = 178;
UPDATE fact_cards SET topic_ru = 'Репрессии', question_ru = 'Чем завершилась жизнь Абдуллы Кадыри?', fact_ru = 'В 1938 году я стал жертвой репрессий. Позже моё имя было реабилитировано, а произведения возвращены народу.' WHERE id = 179;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'Где учился Абдулла Кадыри?', fact_ru = 'В детстве я учился сначала в старой школе, затем в русско-туземной. В медресе изучал арабский и персидский языки.' WHERE id = 1444;
UPDATE fact_cards SET topic_ru = 'Мои первые произведения', question_ru = 'Каковы первые произведения Абдуллы Кадыри?', fact_ru = 'Мои первые произведения опубликованы в 1915–1916 годах. Среди них — драма «Несчастный жених» и рассказ «На улаке».' WHERE id = 1445;
UPDATE fact_cards SET topic_ru = 'Мой рассказ «На улаке»', question_ru = 'О чём рассказ Абдуллы Кадыри «На улаке»?', fact_ru = 'В рассказе «На улаке» я описал впечатления мальчика, попавшего на состязание купкари-улак. Это один из моих первых реалистических рассказов.' WHERE id = 1446;
UPDATE fact_cards SET topic_ru = 'Моя учёба в Москве', question_ru = 'Где учился Абдулла Кадыри в Москве?', fact_ru = 'В 1924 году я поехал в Москву и учился в институте, готовившем журналистов. Там я оттачивал своё литературное мастерство.' WHERE id = 1447;
UPDATE fact_cards SET topic_ru = 'Журнал «Муштум»', question_ru = 'В каком сатирическом журнале активно участвовал Абдулла Кадыри?', fact_ru = 'Я был одним из деятельных авторов сатирического журнала «Муштум», начавшего выходить в 1923 году. В нём печатались мои юмористические статьи и фельетоны.' WHERE id = 1448;
UPDATE fact_cards SET topic_ru = 'Мои сатирические герои', question_ru = 'Каких сатирических героев создал Абдулла Кадыри?', fact_ru = 'В сатирических произведениях я создал героев по имени Калвак Махзум и Ташпулат-задира. Через них я высмеивал пороки старого уклада.' WHERE id = 1449;
UPDATE fact_cards SET topic_ru = '«Обид-кетмень»', question_ru = 'Какую повесть Абдулла Кадыри написал в 1935 году?', fact_ru = 'В 1935 году я написал повесть «Обид-кетмень». В ней изображена жизнь труженика-дехканина Обида.' WHERE id = 1450;
UPDATE fact_cards SET topic_ru = 'Моя реабилитация', question_ru = 'Когда было реабилитировано имя Абдуллы Кадыри?', fact_ru = 'Я погиб в 1938 году. Годы спустя, в 1956 году, моё имя было реабилитировано. После этого мои произведения снова стали издавать, и они вернулись к народу.' WHERE id = 1451;
UPDATE fact_cards SET topic_ru = 'Мой роман в кино', question_ru = 'По какому роману Абдуллы Кадыри снят художественный фильм?', fact_ru = 'По моему роману «Минувшие дни» снят художественный фильм. Так повесть об Отабеке и Кумуш вышла и на киноэкран.' WHERE id = 1452;
UPDATE fact_cards SET topic_ru = 'Моя память', question_ru = 'Как увековечена память Абдуллы Кадыри?', fact_ru = 'Большой парк отдыха в Ташкенте назван моим именем. В годы независимости мне присуждены Государственная премия имени Алишера Навои и орден «Мустакиллик».' WHERE id = 1453;
